import { updateMyProfile } from '../services/api';

const STORAGE_KEY = 'app_language';
const ONBOARDING_STORAGE_KEY = 'has_seen_onboarding';
const SYSTEM_LANGUAGE = 'system';
const DEFAULT_LANGUAGE = 'en';
const APP_LANGUAGE_CODES = ['en', 'fr', 'es', 'pt', 'zh', 'hi', 'ar', 'bn', 'ru', 'ja', 'de', 'id', 'ur'];
const SUPPORTED_LANGUAGES = [SYSTEM_LANGUAGE, ...APP_LANGUAGE_CODES];

function getDeviceLanguageCode() {
  try {
    const locale = Intl?.DateTimeFormat?.().resolvedOptions?.().locale || '';
    const normalized = String(locale).toLowerCase();
    const base = normalized.split(/[-_]/)[0] || '';

    if (base === 'in') return 'id';
    if (APP_LANGUAGE_CODES.includes(base)) return base;
    return DEFAULT_LANGUAGE;
  } catch (_) {
    return DEFAULT_LANGUAGE;
  }
}

