// Ensure every supported language has a working translation table by falling back to English.
const FALLBACK_LANGUAGE_CODES = ['zh', 'hi', 'ar', 'bn', 'ru', 'ja', 'de', 'id', 'ur'];
for (const code of FALLBACK_LANGUAGE_CODES) {
  const existing = MESSAGES[code] || {};
  MESSAGES[code] = { ...MESSAGES.en, ...existing };
}

export const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(DEFAULT_LANGUAGE);
  const [languagePreference, setLanguagePreference] = useState(DEFAULT_LANGUAGE);

  const activeLanguage = useMemo(() => {
    if (
      languagePreference &&
      languagePreference !== SYSTEM_LANGUAGE &&
      APP_LANGUAGE_CODES.includes(languagePreference)
    ) {
      return languagePreference;
    }
    return language;
  }, [language, languagePreference]);

  useEffect(() => {
    (async () => {
      try {
        const hasSeenOnboarding = await AsyncStorage.getItem(ONBOARDING_STORAGE_KEY);
        if (hasSeenOnboarding !== '1') {
          setLanguagePreference(DEFAULT_LANGUAGE);
          setLanguage(DEFAULT_LANGUAGE);
          await AsyncStorage.setItem(STORAGE_KEY, DEFAULT_LANGUAGE);
          return;
        }

        const saved = await AsyncStorage.getItem(STORAGE_KEY);

        if (saved === SYSTEM_LANGUAGE) {
          setLanguagePreference(SYSTEM_LANGUAGE);
          setLanguage(getDeviceLanguageCode());
          return;
        }

        if (APP_LANGUAGE_CODES.includes(saved)) {
          setLanguagePreference(saved);
          setLanguage(saved);
          return;
        }

        const detected = getDeviceLanguageCode();
        setLanguagePreference(detected);
        setLanguage(detected);
        await AsyncStorage.setItem(STORAGE_KEY, detected);
      } catch (e) {
        console.warn('Failed to load language:', e?.message || e);
      }
    })();
  }, []);

  const changeLanguage = async (next) => {
    if (!SUPPORTED_LANGUAGES.includes(next)) return;
    const resolvedLanguage = next === SYSTEM_LANGUAGE ? getDeviceLanguageCode() : next;

    const shouldSyncLanguage = async () => {
      try {
        return Boolean(await AsyncStorage.getItem('user'));
      } catch (_) {
        return false;
      }
    };

    if (next === SYSTEM_LANGUAGE) {
      setLanguagePreference(SYSTEM_LANGUAGE);
      setLanguage(resolvedLanguage);
      try {
        await AsyncStorage.setItem(STORAGE_KEY, SYSTEM_LANGUAGE);
      } catch (e) {
        console.warn('Failed to save language:', e?.message || e);
      }

      if (auth.currentUser && (await shouldSyncLanguage())) {
        try {
          await updateMyProfile({ language: resolvedLanguage });
        } catch (e) {
          console.warn('Failed to sync language preference:', e?.message || e);
        }
      }
      return;
    }

    setLanguagePreference(next);
    setLanguage(next);
    try {
      await AsyncStorage.setItem(STORAGE_KEY, next);
    } catch (e) {
      console.warn('Failed to save language:', e?.message || e);
    }

    if (auth.currentUser && (await shouldSyncLanguage())) {
      try {
        await updateMyProfile({ language: resolvedLanguage });
      } catch (e) {
        console.warn('Failed to sync language preference:', e?.message || e);
      }
    }
  };

  const t = useMemo(() => {
    const table = MESSAGES[activeLanguage] || MESSAGES.en;
    const englishTable = MESSAGES.en || {};
    return (key, fallback) => table[key] || englishTable[key] || fallback || key;
  }, [activeLanguage]);

  const value = useMemo(
    () => ({
      language,
      activeLanguage,
      languagePreference,
      setLanguage: changeLanguage,
      t,
      supportedLanguages: SUPPORTED_LANGUAGES,
    }),
    [language, activeLanguage, languagePreference, t]
  );

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const ctx = useContext(LanguageContext);
  if (!ctx) {
    throw new Error('useLanguage must be used within LanguageProvider');
  }
  return ctx;
}
